function List<T>({ items, getKey, render }: {
  items: T[]
  getKey: (item: T) => string
  render: (item: T) => React.ReactNode
}) {
  return <ul>{items.map(item => <li key={getKey(item)}>{render(item)}</li>)}</ul>
}
